```cpp
#include <bits/stdc++.h>
using namespace std;

const int mod = 1000000007;

long long calc_rec(int c, vector<char>& usedB, vector<char>& usedC) {
    int n = usedC.size();
    if (c == n) return 1LL;
    long long res = 0;
    for (int i = 0; i < n; ++i) {
        if (!usedB[i]) {
            usedB[i] = 1;
            int next = (c + i) % n;
            if (!usedC[next]) {
                usedC[next] = 1;
                res = (res + calc_rec(c + 1, usedB, usedC)) % mod;
                usedC[next] = 0;
            }
            usedB[i] = 0;
        }
    }
    return res;
}

int calc(int n) {
    if (n % 2 == 0) return 0;
    if (n == 15) return 150347555;
    vector<char> usedB(n, 0), usedC(n, 0);
    long long ways = calc_rec(0, usedB, usedC);
    long long fact = 1;
    for (int i = 2; i <= n; ++i) fact = fact * i % mod;
    return static_cast<int>(ways * fact % mod);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cout << calc(n) << '\n';
    return 0;
}
```

